class SyslogConfigurationNotFound(HTTPError):
    """ Raises when configuration for syslog streaming is not found. """
    def __init__(self, error):
        super(SyslogConfigurationNotFound, self).__init__()
        self.response = error.response if hasattr(error, 'response') else None
        self.request = error.request if hasattr(error, 'request') else None
        if self.response is not None and not self.request and hasattr(self.response, "request"):
            self.request = self.response.request

    def __str__(self):
        return "Syslog streaming configuration was not set or was deleted after streaming was stopped."


class ApiException(Exception):
    """
    Custom exception which should used when requests.exceptions.HTTPError is raised.
    """
    def __init__(self, http_response=None):
        self.status = http_response.status_code
        self.reason = http_response.reason
        self.body = getattr(http_response, "content", None)

        if isinstance(self.body, bytes):
            self.body = self.body.decode("utf-8")

        self.headers = getattr(http_response, "headers", None)

    def __str__(self):
        """Custom error messages for exception"""
        error_message = f"({self.status})\n"\
                        f"Reason: {self.reason}\n"
        if self.headers:
            error_message += f"HTTP response headers: {self.headers}\n"

        if self.body:
            error_message += f"HTTP response body: {self.body}\n"

        return error_message
